import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s2-u03")
C = "A1-A2"

L(1, "Os dias da semana", "maandag, dinsdag… e «op maandag».",
  ["Dizer os dias da semana", "Usar «op» com os dias"],
  vocab=[V("v-maandag","maandag","segunda-feira","noun","de"), V("v-dinsdag","dinsdag","terça-feira","noun","de"), V("v-woensdag","woensdag","quarta-feira","noun","de"),
         V("v-donderdag","donderdag","quinta-feira","noun","de"), V("v-vrijdag","vrijdag","sexta-feira","noun","de"), V("v-zaterdag","zaterdag","sábado","noun","de"),
         V("v-zondag","zondag","domingo","noun","de"), V("v-week","week","semana","noun","de","weken"), V("v-dag","dag","dia","noun","de","dagen")],
  ex=[("Op maandag werk ik.","À segunda-feira trabalho."),("Vandaag is het vrijdag.","Hoje é sexta-feira."),("Tot zaterdag!","Até sábado!")],
  gram=[G("g-dias","Dias da semana","Os dias escrevem-se com **minúscula** e usam **op** para dizer «à/no»: *op dinsdag* (na terça). Para hábitos, também sem preposição ou no plural: *maandags* (às segundas). Todos acabam em **-dag** (dia).",
    [("Op woensdag sport ik.","À quarta-feira faço desporto."),("Ik werk van maandag tot vrijdag.","Trabalho de segunda a sexta.")],
    "Os nomes vêm de deuses e astros (maan = lua, zon = sol, donder = trovão), não de números como «segunda», «terça».")],
  review=["v-vandaag","v-morgen","v-weekend","v-werken"],
  cefr=C, exs=[
    MA([("maandag","segunda-feira"),("dinsdag","terça-feira"),("woensdag","quarta-feira"),("donderdag","quinta-feira"),("vrijdag","sexta-feira")], "Dias úteis.", ["v-maandag","v-dinsdag","v-woensdag","v-donderdag","v-vrijdag"]),
    MA([("zaterdag","sábado"),("zondag","domingo"),("week","semana"),("dag","dia")], "Fim de semana e unidades.", ["v-zaterdag","v-zondag","v-week","v-dag"]),
    TR("pt-nl","À terça-feira trabalho em casa.", ["Op dinsdag werk ik thuis","Ik werk op dinsdag thuis","Dinsdag werk ik thuis"], "op + dia; inversão.", ["v-dinsdag"]),
    FB("Na zaterdag komt ___.", ["zondag"], "Depois de sábado vem domingo.", ["v-zondag"], choices=["zondag","maandag","vrijdag"], tr="Depois de sábado vem domingo."),
    MC("Que dia vem antes de quinta-feira?", ["*woensdag","dinsdag|terça vem antes de quarta.","vrijdag|sexta vem depois."], "woensdag = quarta.", ["v-woensdag"]),
    LI("Tot donderdag!", ["Tot donderdag"], "Até quinta!", "donder = trovão.", ["v-donderdag"]),
    TR("nl-pt","Ik werk van maandag tot vrijdag.", ["Trabalho de segunda a sexta(-feira)"], "van … tot = de … a.", ["v-maandag","v-vrijdag"]),
    FE(["Ik","werk","in","maandag."], 2, "op", "Com os dias usa-se «op»: op maandag. (E os dias escrevem-se com minúscula.)", ["v-maandag"]),
    AR("week","a semana","de", "«De week».", ["v-week"]),
    WO("Hoje é sábado.", ["Vandaag","is","het","zaterdag"], "Vandaag is het + dia.", ["v-zaterdag","v-vandaag"]),
  ], diff=1, mins=5)

L(2, "Os meses do ano", "januari, februari… e «in mei».",
  ["Dizer os meses", "Usar «in» com os meses"],
  vocab=[V("v-maand","maand","mês","noun","de","maanden"), V("v-januari","januari","janeiro","noun",note="Usa-se sem artigo: in januari."), V("v-februari","februari","fevereiro","noun",note="Usa-se sem artigo: in februari."),
         V("v-maart","maart","março","noun",note="Usa-se sem artigo: in maart."), V("v-april","april","abril","noun",note="Usa-se sem artigo: in april."), V("v-mei","mei","maio","noun",note="Usa-se sem artigo: in mei."), V("v-juni","juni","junho","noun",note="Usa-se sem artigo: in juni."),
         V("v-juli","juli","julho","noun",note="Usa-se sem artigo: in juli."), V("v-augustus","augustus","agosto","noun",note="Usa-se sem artigo: in augustus."), V("v-september","september","setembro","noun",note="Usa-se sem artigo: in september."),
         V("v-oktober","oktober","outubro","noun",note="Usa-se sem artigo: in oktober."), V("v-november","november","novembro","noun",note="Usa-se sem artigo: in november."), V("v-december","december","dezembro","noun",note="Usa-se sem artigo: in december.")],
  ex=[("Mijn verjaardag is in mei.","O meu aniversário é em maio."),("In augustus ga ik op vakantie.","Em agosto vou de férias."),("Januari is koud.","Janeiro é frio.")],
  gram=[G("g-meses","Meses","Os meses escrevem-se com **minúscula** e usam **in**: *in maart*. São parecidos com os portugueses, mas atenção à pronúncia: **juni** ≈ «iúni», **juli** ≈ «iúli» (o j soa como i). Para distinguir, muitos dizem «juni» e «julij» na fala.",
    [("in januari","em janeiro"),("eind december","no fim de dezembro")])],
  review=["v-verjaardag","v-koud","v-in"],
  cefr=C, exs=[
    MA([("maart","março"),("mei","maio"),("juni","junho"),("juli","julho"),("augustus","agosto")], "Meses (1).", ["v-maart","v-mei","v-juni","v-juli","v-augustus"]),
    MA([("januari","janeiro"),("april","abril"),("oktober","outubro"),("december","dezembro")], "Meses (2).", ["v-januari","v-april","v-oktober","v-december"]),
    TR("pt-nl","O meu aniversário é em maio.", ["Mijn verjaardag is in mei"], "in + mês.", ["v-mei","v-verjaardag"]),
    TR("nl-pt","In augustus ga ik op vakantie.", ["Em agosto vou de férias","Em agosto vou (estar )de férias"], "op vakantie gaan = ir de férias.", ["v-augustus"]),
    MC("Qual é o mês a seguir a junho?", ["*juli","juni|É o próprio junho.","augustus|Vem depois de julho."], "juni → juli.", ["v-juli"]),
    LI("Het is koud in februari.", ["Het is koud in februari"], "Faz frio em fevereiro.", "februari ≈ «fêbruári».", ["v-februari"]),
    FB("Kerstmis is in ___.", ["december"], "Natal = dezembro.", ["v-december"], choices=["december","september","november"], tr="O Natal é em dezembro."),
    AR("maand","o mês","de", "«De maand».", ["v-maand"]),
    FE(["Ik","ga","op","juli","op","vakantie."], 2, "in", "Com meses usa-se «in»: in juli.", ["v-juli"]),
    TR("pt-nl","um ano tem doze meses", ["een jaar heeft twaalf maanden"], "maand → maanden.", ["v-maand","v-jaar"]),
  ], diff=2, mins=5)

L(3, "Datas", "Welke datum is het? Op 12 mei. Volgende week.",
  ["Perguntar e dizer a data", "Usar volgende e vorige"],
  vocab=[V("v-volgende","volgende","próximo|seguinte","adjective"), V("v-vorige","vorige","passado|anterior","adjective",note="vorige week = a semana passada."),
         V("v-overmorgen","overmorgen","depois de amanhã","adverb"), V("v-eergisteren","eergisteren","anteontem","adverb")],
  ex=[("Welke datum is het vandaag?","Que dia é hoje (data)?"),("Het is maandag 3 mei.","É segunda-feira, 3 de maio."),("Volgende week ga ik naar Portugal.","Na próxima semana vou a Portugal."),("Vorige maand was ik ziek.","No mês passado estive doente.")],
  gram=[G("g-datas","Escrever e dizer datas","Data: **dia + mês** sem «de»: *3 mei*, *op 12 oktober*. Lê-se *drie mei* (ou *de derde mei*). Escreve-se 03-05-2027 (dia-mês-ano). Para «na próxima/passada»: **volgende / vorige** + week, maand, jaar — sem preposição.",
    [("op 1 januari","no dia 1 de janeiro"),("volgend jaar","no próximo ano","Com palavras het: volgend jaar, vorig jaar (sem -e).")],
    "Em português «3 de maio»; em neerlandês, «3 mei», sem preposição.")],
  review=["v-datum","v-eerste","v-week","v-maand","v-gisteren"],
  cefr=C, exs=[
    MA([("volgende","próximo"),("vorige","passado"),("overmorgen","depois de amanhã"),("eergisteren","anteontem")], "Referências de tempo.", ["v-volgende","v-vorige","v-overmorgen","v-eergisteren"]),
    TR("pt-nl","Na próxima semana vou a Portugal.", ["Volgende week ga ik naar Portugal","Ik ga volgende week naar Portugal"], "Sem preposição: volgende week.", ["v-volgende","v-week"]),
    TR("nl-pt","Welke datum is het vandaag?", ["Que dia é hoje","Qual é a data de hoje"], "datum = data.", ["v-datum"]),
    TR("pt-nl","no dia doze de maio", ["op twaalf mei","op 12 mei"], "op + dia + mês.", ["v-mei"]),
    MC("Como se diz «o ano passado»?", ["*vorig jaar","vorige jaar|«jaar» é het: vorig (sem -e).","volgende jaar|«volgend» = próximo."], "het jaar → vorig jaar.", ["v-vorige","v-jaar"]),
    FE(["Ik","ben","jarig","op","12","van","mei."], 5, "(retirar)", "Sem «van»: op 12 mei.", ["v-mei"]),
    LI("Overmorgen is het zondag.", ["Overmorgen is het zondag"], "Depois de amanhã é domingo.", "over + morgen.", ["v-overmorgen"]),
    FB("Vandaag is het dinsdag. ___ was het maandag.", ["Gisteren"], "Ontem = gisteren.", ["v-gisteren"], choices=["Gisteren","Morgen","Overmorgen"], tr="Hoje é terça. Ontem foi segunda."),
    DL([("Médico","Wanneer bent u geboren?","Quando nasceu?"),("Ana","")], ["*Op 14 juni 1990.","In 14 juni.|Com datas usa-se «op».","Ik ben 34.|Isso é a idade."], "op + data.", ["v-juni"]),
    WO("No mês passado estive doente.", ["Vorige","maand","was","ik","ziek"], "Inversão.", ["v-vorige","v-maand"], alt=["Ik was vorige maand ziek"]),
  ], diff=2, mins=6)

L(4, "A agenda: quando tens tempo?", "Marcar encontros: Kun je op dinsdag?",
  ["Propor e aceitar dias e horas", "Dizer que está livre ou ocupado"],
  vocab=[V("v-agenda","agenda","agenda","noun","de"), V("v-afspraak","afspraak","encontro|marcação|consulta","noun","de","afspraken"),
         V("v-kunnen","kunnen","poder|conseguir","verb",note="ik kan, jij kunt (kun je?), hij kan"), V("v-vrij","vrij","livre|de folga","adjective"),
         V("v-passen","passen","dar jeito|convir","verb",note="Dat past goed = isso dá jeito.")],
  ex=[("Kun je op dinsdag?","Podes na terça?"),("Ik ben woensdag vrij.","Estou livre na quarta."),("Ik heb een afspraak bij de tandarts.","Tenho consulta no dentista."),("Past donderdag?","Quinta dá jeito?")],
  gram=[G("g-kunnen-intro","Kunnen","**kunnen** = poder/conseguir: ik **kan**, jij **kunt** (na pergunta: **kun je?**), u **kunt**, hij **kan**, wij **kunnen**. Para marcar: *Kun je op vrijdag?* (podes na sexta?). Os verbos modais serão estudados a fundo na Secção 4.",
    [("Ik kan niet op maandag.","Não posso à segunda.")])],
  review=["v-tijd","v-afspreken","v-volgende","v-druk"],
  cefr=C, exs=[
    MA([("agenda","agenda"),("afspraak","marcação"),("vrij","livre"),("kunnen","poder"),("passen","dar jeito")], "Marcar encontros.", ["v-agenda","v-afspraak","v-vrij","v-kunnen","v-passen"]),
    CJ("kunnen","jij","___ je op vrijdag?", ["Kun"], "Pergunta: kun je…?", ["v-kunnen"]),
    CJ("kunnen","ik","Ik ___ niet op maandag.", ["kan"], "ik kan.", ["v-kunnen"]),
    TR("pt-nl","Estou livre na quarta-feira.", ["Ik ben (op )woensdag vrij","Op woensdag ben ik vrij","Woensdag ben ik vrij"], "vrij zijn = estar livre.", ["v-vrij","v-woensdag"]),
    TR("nl-pt","Ik heb een afspraak bij de tandarts.", ["Tenho (uma )consulta no dentista","Tenho uma marcação no dentista"], "afspraak = marcação/consulta.", ["v-afspraak"]),
    AR("afspraak","a marcação","de", "«De afspraak».", ["v-afspraak"]),
    DL([("Tom","Kun je volgende week dinsdag?","Podes na próxima terça?"),("Eva","Nee, dan ben ik druk. Past donderdag?","Não, nesse dia estou ocupada. Quinta dá jeito?"),("Tom","")], ["*Ja, donderdag past goed!","Ja, ik ben dinsdag.|Não responde.","Nee, ik heb geen agenda.|Não faz sentido."], "Aceitar o dia proposto.", ["v-passen"]),
    FE(["Kunt","je","morgen?"], 0, "Kun", "Na pergunta com je: kun je?", ["v-kunnen"]),
    LI("Wanneer heb je tijd?", ["Wanneer heb je tijd"], "Quando tens tempo?", "Pergunta essencial para marcar.", ["v-tijd"]),
    SW("Responda a um amigo: não pode na segunda, mas está livre na quarta à noite.", ["Ik kan niet op maandag(,) maar ik ben woensdagavond vrij","Maandag kan ik niet(,) maar woensdagavond ben ik vrij"],
       ["Recusa a segunda com «ik kan niet»","Propõe a quarta com «vrij»","Liga as ideias com «maar»"], 7, "Modelo: «Ik kan niet op maandag, maar ik ben woensdagavond vrij.»", ["v-kunnen","v-vrij"]),
  ], diff=2, mins=6)

L(5, "Feriados neerlandeses", "Revisão: datas, dias e meses com o calendário dos Países Baixos.",
  ["Falar de datas importantes", "Conhecer os principais feriados"],
  vocab=[V("v-koningsdag","Koningsdag","Dia do Rei","noun",note="27 de abril: festa nacional, tudo em cor-de-laranja."), V("v-kerst","Kerstmis","Natal","noun",note="Também «de kerst»; dois dias: 25 e 26 de dezembro."),
         V("v-feestdag","feestdag","feriado","noun","de","feestdagen")],
  ex=[("Koningsdag is op 27 april.","O Dia do Rei é a 27 de abril."),("Op 5 mei is het Bevrijdingsdag.","A 5 de maio é o Dia da Libertação."),("Fijne feestdagen!","Boas festas!")],
  review=["v-april","v-mei","v-december","v-volgende","v-op-tijd"],
  cefr=C, exs=[
    MA([("Koningsdag","Dia do Rei"),("Kerstmis","Natal"),("feestdag","feriado"),("Nieuwjaar","Ano Novo")], "Feriados.", ["v-koningsdag","v-kerst","v-feestdag"]),
    MC("Quando é o Koningsdag?", ["*27 de abril","5 de maio|É o Dia da Libertação.","25 de dezembro|É o Natal."], "Koningsdag = 27 april.", ["v-koningsdag","v-april"]),
    TR("nl-pt","Fijne feestdagen!", ["Boas festas"], "Expressão de dezembro.", ["v-feestdag"]),
    TR("pt-nl","O Natal é em dezembro.", ["Kerstmis is in december","Kerst is in december"], "in + mês.", ["v-kerst","v-december"]),
    LI("Koningsdag is op zevenentwintig april.", ["Koningsdag is op zevenentwintig april","Koningsdag is op 27 april"], "O Dia do Rei é a 27 de abril.", "zeven-en-twintig.", ["v-koningsdag"]),
    FB("Op Koningsdag draagt iedereen ___.", ["oranje"], "A cor nacional (da casa real) é o laranja.", ["v-koningsdag"], choices=["oranje","blauw","groen"], tr="No Dia do Rei toda a gente veste cor-de-laranja."),
    AR("feestdag","o feriado","de", "«De feestdag».", ["v-feestdag"]),
    CO("text","Koningsdag", "Op 27 april is het Koningsdag. Dat is de verjaardag van koning Willem-Alexander. In heel Nederland is het feest. Mensen dragen oranje kleren en op straat is er een grote vrijmarkt: iedereen mag spullen verkopen.",
       [("O que se celebra?", ["*O aniversário do rei","O Natal","O Ano Novo"]),("O que acontece na rua?", ["*Um grande mercado livre","Um desfile militar","Nada: está tudo fechado"])],
       "vrijmarkt = mercado onde todos podem vender.", ["v-koningsdag"]),
    WO("No próximo ano vou a Amesterdão no Dia do Rei.", ["Volgend","jaar","ga","ik","op","Koningsdag","naar","Amsterdam"], "Inversão; tempo antes do lugar.", ["v-volgende","v-koningsdag"]),
    TR("pt-nl","Que dia da semana é o dia 5 de maio?", ["Welke dag is (het op )5 mei","Welke dag is (het op )vijf mei"], "welke dag = que dia.", ["v-dag"]),
  ], diff=2, mins=6)

W()
